def text_paths(text,font='Manrope',weight=800,size=100,x=0,y=76,color='#202730',tracking=0,dotcolor=None):
 f=fonts[(font,weight)];buf=io.BytesIO();f.save(buf);face=hb.Face(buf.getvalue());hf=hb.Font(face);upm=f['head'].unitsPerEm;hf.scale=(upm,upm);b=hb.Buffer();b.add_str(text);b.guess_segment_properties();hb.shape(hf,b)
 gs=f.getGlyphSet();order=f.getGlyphOrder();parts=[];cursor=0
 for info,pos in zip(b.glyph_infos,b.glyph_positions):
  pen=SVGPathPen(gs);gs[order[info.codepoint]].draw(pen);fill=dotcolor if dotcolor and info.cluster==len(text)-1 else color
  transform=f'translate({x+(cursor+pos.x_offset)*size/upm:.3f} {y-pos.y_offset*size/upm:.3f}) scale({size/upm:.6f} {-size/upm:.6f})'
  if dotcolor and info.cluster==len(text)-1:
   parts.append(f'<circle fill="{fill}" transform="{transform}" cx="320" cy="136" r="136"/>')
  else:
   parts.append(f'<path fill="{fill}" transform="{transform}" d="{pen.getCommands()}"/>')
  cursor+=pos.x_advance+tracking*upm/size
 return ''.join(parts),cursor*size/upm-tracking

def symbol(color='#247459',x=0,y=0,size=96):
 return f'<g transform="translate({x} {y}) scale({size/24})" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round"><path d="M12 2v20M2 12h20M5 5l14 14M5 19 19 5"/></g>'

def logo(kind='horizontal',ink='#202730',green='#247459'):
 word,width=text_paths('nexo.',color=ink,dotcolor=green,tracking=-5.8)
 if kind=='horizontal':return symbol(green)+f'<g transform="translate(120 0)">{word}</g>',width+120,96
 if kind=='logotipo':return word,width,96
 if kind=='isotipo':return symbol(green),96,96
 w=max(width,220);return symbol(green,(w-96)/2,0)+f'<g transform="translate({(w-width)/2} 130)">{word}</g>',w,226

def svg_doc(content,w,h,bg=None,pad=24,title='Nexo — identidad visual'):
 return f'<svg xmlns="http://www.w3.org/2000/svg" width="{w+pad*2:.2f}" height="{h+pad*2:.2f}" viewBox="{-pad} {-pad} {w+pad*2:.2f} {h+pad*2:.2f}" role="img"><title>{html.escape(title)}</title>'+ (f'<rect x="{-pad}" y="{-pad}" width="{w+pad*2}" height="{h+pad*2}" fill="{bg}"/>' if bg else '')+content+'</svg>'

def render(svg,png,width=2000,jpg=None):
 cairosvg.svg2png(url=str(svg),write_to=str(png),output_width=width)
 if jpg:
  im=Image.open(png).convert('RGBA');bg=Image.new('RGB',im.size,'white');bg.paste(im,mask=im.getchannel('A'));bg.save(jpg,quality=94,subsampling=0)

