def rgb(h):return tuple(int(h[i:i+2],16) for i in (1,3,5))
def cmyk(h):
 r,g,b=[v/255 for v in rgb(h)];k=1-max(r,g,b)
 return tuple(round(v*100) for v in ((1-r-k)/(1-k) if k<1 else 0,(1-g-k)/(1-k) if k<1 else 0,(1-b-k)/(1-k) if k<1 else 0,k))
def lum(h):
 vals=[v/255 for v in rgb(h)];vals=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in vals];return sum(v*w for v,w in zip(vals,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([lum(a),lum(b)]);return (y+.05)/(x+.05)
records=[{'name':n,'hex':h,'rgb':rgb(h),'cmyk_approx_percent':cmyk(h),'use':u} for n,h,u in palette]
